public struct Transaction {
    public var rawTransactionId: String
    public var blockTimeInSeconds: Int64
    public var minedHeight: Int64
    public var value: String
    public var fee: String?
    public var toAddress: String?
    public var isShielding: Bool
    public var isExpired: Bool
    public var memos: [String]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(rawTransactionId: String, blockTimeInSeconds: Int64, minedHeight: Int64, value: String, fee: String?, toAddress: String?, isShielding: Bool, isExpired: Bool, memos: [String]) {
        self.rawTransactionId = rawTransactionId
        self.blockTimeInSeconds = blockTimeInSeconds
        self.minedHeight = minedHeight
        self.value = value
        self.fee = fee
        self.toAddress = toAddress
        self.isShielding = isShielding
        self.isExpired = isExpired
        self.memos = memos
    }
}

#if compiler(>=6)
extension Transaction: Sendable {}
#endif


extension Transaction: Equatable, Hashable {
    public static func ==(lhs: Transaction, rhs: Transaction) -> Bool {
        if lhs.rawTransactionId != rhs.rawTransactionId {
            return false
        }
        if lhs.blockTimeInSeconds != rhs.blockTimeInSeconds {
            return false
        }
        if lhs.minedHeight != rhs.minedHeight {
            return false
        }
        if lhs.value != rhs.value {
            return false
        }
        if lhs.fee != rhs.fee {
            return false
        }
        if lhs.toAddress != rhs.toAddress {
            return false
        }
        if lhs.isShielding != rhs.isShielding {
            return false
        }
        if lhs.isExpired != rhs.isExpired {
            return false
        }
        if lhs.memos != rhs.memos {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(rawTransactionId)
        hasher.combine(blockTimeInSeconds)
        hasher.combine(minedHeight)
        hasher.combine(value)
        hasher.combine(fee)
        hasher.combine(toAddress)
        hasher.combine(isShielding)
        hasher.combine(isExpired)
        hasher.combine(memos)
    }
}



