private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 29
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_zcash_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_zcash_checksum_func_create_transfer() != 61268) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_derive_unified_address() != 34142) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_derive_viewing_key() != 52078) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_emit_existing_transactions() != 10590) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_get_birthday_height() != 3517) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_get_latest_network_height() != 10901) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_initialize() != 53974) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_ironwood_activation_height() != 58583) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_is_valid_address() != 46019) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_poll() != 33946) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_propose_fulfilling_payment_uri() != 49379) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_propose_orchard_to_ironwood_migration() != 31438) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_propose_transfer() != 45967) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_rescan() != 17200) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_set_document_directory() != 27339) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_shield_funds() != 4791) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zcash_checksum_func_stop() != 20284) {
        return InitializationResult.apiChecksumMismatch
    }

    return InitializationResult.ok
}()

// Make the ensure init function public so that other modules which have external type references to
// our types can call it.
public func uniffiEnsureZcashInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

